    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Den relativa osäkerheten är en andel. Hur får du en absolut osäkerhet från den?</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": true,
    "svarFormat": "numeriskt",
    "svarEnhet": "g/cm³"
