    "geogebra": false,
    "ledtrad": "<p>Skriv osäkerheten för varje längd som en andel av just den längden.</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": true,
    "svarEnhet": "cm³",
    "svarFormat": "numeriskt"
