    "rättSvar": null,
    "tolerans": null,
    "självrättning": false,
    "familjNyckelTidigare": "densitet__densitet_med_geometrisk_volym",
    "ledtrad": "<p>Jämför lutningarna och deras enheter med de givna densiteterna.</p>",
    "traningsniva": 2,
