    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Jämför med en lika stor kula helt av stål. Vilken massa försvinner när stål ersätts av aluminium?</p>",
    "traningsniva": 4,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "cm",
    "svarFormat": "numeriskt"
