    "självrättning": false,
    "ledtrad": "<p>Jämför sträckorna fram till varje fordons egen sluttid.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "miniräknare": true,
    "geogebra": false,
    "spel": false,
    "manuellKomplettering": true
