    "familjNyckelTidigare": "ritakrafter__frilaggning_med_spannkraft",
    "ledtrad": "<p>Spännkraften verkar längs snöret. Vad måste dess två komponenter balansera?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "miniräknare": false,
    "geogebra": false,
    "manuellKomplettering": true,
    "typ": "Sned snörkraft"
