    "spel": false,
    "familjNyckelTidigare": "ritakrafter__frilaggning_med_friktion",
    "ledtrad": "<p>Vilken yta glider åt vilket håll relativt den andra?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "miniräknare": false,
    "geogebra": false,
    "manuellKomplettering": true,
    "typ": "Glidfriktion som drivkraft"
