    "familjNyckelFöreHierarki": "blandat__krafter_och_rorelse",
    "familjTidigare": "Krafter och rörelse",
    "ledtrad": "<p>Gäller samma hoptryckning under hela rörelsen?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "miniräknare": true,
    "geogebra": false,
    "spel": false,
    "manuellKomplettering": true,
