    "rättSvar": null,
    "tolerans": null,
    "självrättning": false,
    "spel": false,
    "familjNyckelTidigare": "ritakrafter__frilaggning_med_spannkraft",
    "ledtrad": "<p>Jämför kraftvektorer och kraftbelopp: det är inte samma slags summa.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "miniräknare": true,
    "geogebra": false,
