    "tolerans": null,
    "självrättning": false,
    "ledtrad": "<p>Skilj på energi som lämnar motorn som mekaniskt arbete och energi som överförs på andra sätt.</p>",
    "traningsniva": 2,
    "miniräknare": true,
    "geogebra": false,
