    "rättSvar": null,
    "tolerans": null,
    "självrättning": false,
    "ledtrad": "<p>Betyder utströmningsfarten fart relativt marken eller relativt raketen?</p>",
    "traningsniva": 4,
    "miniräknare": true,
    "geogebra": false,
    "arbetsinsats": 2,
    "spel": false,
    "manuellKomplettering": true
