    "självrättning": false,
    "familjTidigare": "Effekt som energi per tid",
    "familjNyckelFöreHierarki": "effekt__effekt_som_energi_per_tid",
    "ledtrad": "<p>Bestäm först vattenmängden. Skilj sedan mellan energi, effekt och ekonomiskt värde.</p>",
    "traningsniva": 4,
    "typ": "energiutbyte från regnvatten",
    "miniräknare": true,
    "geogebra": false,
    "arbetsinsats": 2,
    "spel": false,
    "manuellKomplettering": true
