    "självrättning": true,
    "omrTidigare": "blandat",
    "familjNyckelFöreHierarki": "blandat__rorelsemangd_och_impuls",
    "ledtrad": "<p>Följ energin fram till stöten. Vilken storhet bevaras genom själva stöten?</p>",
    "traningsniva": 4,
    "miniräknare": true,
    "geogebra": false,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "m/s",
    "svarFormat": "numeriskt"
