    "tolerans": 0,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Areaförhållandet ger diametrarnas kvot i kvadrat.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "cm",
    "svarFormat": "numeriskt"
