    "ledtrad": "<p>Vilken sida av sugkoppen har högst tryck?</p>",
    "traningsniva": 3,
    "typ": "sugkopp och tryckskillnad",
    "miniräknare": true,
    "geogebra": false,
    "arbetsinsats": 2,
    "spel": false,
    "manuellKomplettering": true
