    "tolerans": 6.825,
    "självrättning": true,
    "svarFormat": "numeriskt",
    "svarEnhet": "kJ",
    "familjNyckelTidigare": "fasandring__smaltning_och_frysning",
    "ledtrad": "<p>Kyl det flytande vattnet från 20 till 0 °C. Under själva fasövergången ändras inte temperaturen.</p>"
