    "tolerans": 1.08e-06,
    "självrättning": true,
    "miniräknare": false,
    "geogebra": false,
    "ledtrad": "<p>Använd \\(\\Delta E=qU\\) och håll reda på laddningens tecken om riktningen efterfrågas.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "J"
