    "tolerans": 0,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Vilken delkoppling kan du ersätta först för att förenkla systemet?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "N/m",
