    "tolerans": 0,
    "självrättning": true,
    "ledtrad": "<p>Både reaktionen och bromsningen måste rymmas inom avståndet.</p>",
    "traningsniva": 4,
    "arbetsinsats": 2,
    "geogebra": false,
