    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>De två sträckorna och tiderna ger farterna före och efter förändringen.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "m/s²",
    "svarFormat": "numeriskt"
