    "rättSvar": 3.09,
    "tolerans": 0.046349999999999995,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Skriv \\(p_1V_1/T_1=p_2V_2/T_2\\). Använd kelvin och totaltryck.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "cm³"
