    "ledtrad": "<p>Farten i slutet av fallet blir startfart för bromsningen.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "ms",
    "svarFormat": "numeriskt"
