    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Modellera stången som en cylinder och använd halva diametern som radie.</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": true,
    "svarEnhet": "kg",
