    "självrättning": false,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Vilken massa skulle ett massivt guldblock med dessa mått ha?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": false,
    "manuellKomplettering": true
