    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Vattennivåns ökning ger volymen, förutsatt att inga bubblor följer med.</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": false,
    "manuellKomplettering": true
